/* Vix Voice desktop client — fluxo único e estável. */
const $=id=>document.getElementById(id),SESSION='vix-session';
const state={identity:null,server:null,channel:'geral',messages:[]};
let selectedVoiceChannel={id:'Geral',name:'Geral'};
const initials=name=>(name||'?').trim().slice(0,2).toUpperCase()||'?';
async function api(path,options={}){const headers={'content-type':'application/json',...options.headers},controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);if(state.identity?.token)headers.Authorization=`Bearer ${state.identity.token}`;try{const r=await fetch(path,{...options,headers,signal:options.signal||controller.signal}),data=await r.json().catch(()=>({error:'Resposta inválida do servidor.'}));if(!r.ok)throw Error(data.error||'Não foi possível concluir a operação.');return data}catch(error){if(error.name==='AbortError')throw Error('O servidor demorou mais de 10 segundos para responder.');throw error}finally{clearTimeout(timeout)}}
function setIdentity(identity){state.identity=identity;$('profile-name').textContent=identity.name;$('profile-avatar').textContent=initials(identity.name);$('profile-avatar').style.background=identity.color||'#5865f2';$('profile-status').textContent='Online'}
function auth(show){$('join-modal').hidden=!show;if(show)$('auth-error').textContent=''}
const picker=document.createElement('section');picker.id='server-picker';picker.className='join-modal';picker.hidden=true;picker.innerHTML='<div class="join-card"><h1>Seus servidores</h1><p id="picker-copy">Escolha uma comunidade ou crie a sua.</p><div id="picker-list"></div><p id="picker-error" role="alert"></p><button id="picker-create">Criar servidor</button><button id="picker-join" type="button" style="margin-top:10px;background:#41434a">Entrar com convite</button><button id="picker-close" type="button" style="margin-top:10px;background:transparent;color:#b5bac1">Continuar sem servidor</button></div>';document.body.append(picker);
function closePicker(){picker.hidden=true}$('picker-close').onclick=closePicker;picker.onclick=e=>{if(e.target===picker)closePicker()};addEventListener('keydown',e=>{if(e.key==='Escape')closePicker()});
async function openPicker(){if(!state.identity)return auth(true);const list=$('picker-list');list.replaceChildren();$('picker-error').textContent='';picker.hidden=false;try{const {servers}=await api('/api/servers');$('picker-copy').textContent=servers.length?'Escolha uma comunidade ou crie a sua.':'Você ainda não participa de nenhum servidor. Crie o seu ou use um convite.';for(const server of servers){const b=document.createElement('button');b.type='button';b.textContent=`${server.icon||initials(server.name)}  ${server.name}`;b.style.cssText='margin:4px 0;background:#41434a;text-align:left';b.onclick=()=>loadServer(server);list.append(b)}renderRail(servers)}catch(e){localStorage.removeItem(SESSION);state.identity=null;picker.hidden=true;auth(true);$('auth-error').textContent='Sua sessão expirou. Entre novamente.'}}
async function createServer(){const name=prompt('Nome do novo servidor:')?.trim();if(!name)return;try{await loadServer(await api('/api/servers',{method:'POST',body:JSON.stringify({name})}))}catch(e){$('picker-error').textContent=e.message}}
async function joinServer(){const invite=prompt('Código do convite:')?.trim();if(!invite)return;try{const joined=await api(`/api/servers/join/${encodeURIComponent(invite)}`,{method:'POST'}),{servers}=await api('/api/servers'),server=servers.find(x=>x.id===joined.id);if(!server)throw Error('Servidor não encontrado.');await loadServer(server)}catch(e){$('picker-error').textContent=e.message}}
$('picker-create').onclick=createServer;$('picker-join').onclick=joinServer;
function renderRail(servers){const rail=document.querySelector('.servers'),add=rail.querySelector('.server.add');rail.querySelectorAll('[data-server-id]').forEach(x=>x.remove());for(const server of servers){const b=document.createElement('button');b.className=`server ${state.server?.id===server.id?'active':''}`;b.dataset.serverId=server.id;b.title=server.name;b.textContent=server.icon||initials(server.name);b.onclick=()=>loadServer(server);rail.insertBefore(b,add)}}
async function loadServer(server){try{const details=await api(`/api/servers/${server.id}`),channels=(details.channels||[]).map(x=>typeof x==='string'?x:x.name).filter(Boolean);state.server=server;state.messages=details.messages||[];state.channel=channels.includes('geral')?'geral':channels[0]||'geral';$('server-name').textContent=server.name;$('server-name').title=`Código do convite: ${server.invite}`;renderChannels(channels);renderMessages();closePicker();const {servers}=await api('/api/servers');renderRail(servers)}catch(e){$('picker-error').textContent=e.message;picker.hidden=false}}
function renderChannels(channels){const list=$('text-channels');list.replaceChildren();for(const channel of channels){const b=document.createElement('button');b.className=`channel ${channel===state.channel?'active':''}`;b.innerHTML='<span class="hash">#</span>';b.append(channel);b.onclick=()=>{state.channel=channel;renderChannels(channels);renderMessages()};list.append(b)}$('channel-title').textContent=state.channel;$('message').placeholder=`Envie uma mensagem em #${state.channel}`}
function renderMessages(){const out=$('messages');out.replaceChildren();const welcome=document.createElement('div');welcome.className='welcome';welcome.innerHTML='<div class="welcome-icon">#</div>';const title=document.createElement('h1');title.textContent=`Boas-vindas a #${state.channel}!`;const copy=document.createElement('p');copy.textContent='Este é o começo deste canal.';welcome.append(title,copy);out.append(welcome);for(const item of state.messages.filter(x=>x.channel===state.channel)){const row=document.createElement('article');row.className='message';const avatar=document.createElement('div');avatar.className='avatar';avatar.textContent=initials(item.author);const body=document.createElement('div'),head=document.createElement('div'),text=document.createElement('div'),time=document.createElement('span');head.className='message-head';text.className='message-text';time.className='message-time';head.textContent=item.author;time.textContent=` hoje às ${new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date(item.created))}`;head.append(time);text.textContent=item.text;body.append(head,text);row.append(avatar,body);out.append(row)}out.scrollTop=out.scrollHeight}
async function sendMessage(event){event.preventDefault();const text=$('message').value.trim();if(!text||!state.server)return;try{const {message}=await api(`/api/servers/${state.server.id}/messages`,{method:'POST',body:JSON.stringify({channel:state.channel,text})});state.messages.push(message);$('message').value='';renderMessages()}catch(e){alert(e.message)}}
async function addChannel(){if(!state.server)return openPicker();const name=prompt('Nome do canal:')?.trim();if(!name)return;try{await api(`/api/servers/${state.server.id}/channels`,{method:'POST',body:JSON.stringify({name})});await loadServer(state.server)}catch(e){alert(e.message)}}
function toggleAuth(){const mode=$('auth-toggle').dataset.mode==='login'?'register':'login',login=mode==='login';$('auth-toggle').dataset.mode=mode;$('auth-title').textContent=login?'Entre na sua conta':'Crie sua conta';$('auth-copy').textContent=login?'Use seus dados para continuar no Vix Voice.':'Seu perfil ficará disponível nos seus servidores.';$('name').hidden=login;document.querySelector('label[for="name"]').hidden=login;$('name').required=!login;$('auth-submit').textContent=login?'Entrar no Vix Voice':'Criar conta e entrar';$('auth-toggle').textContent=login?'Ainda não tenho uma conta':'Já tenho uma conta';$('auth-error').textContent=''}
async function submitAuth(event){event.preventDefault();const mode=$('auth-toggle').dataset.mode||'register';try{const data=await api(`/api/auth/${mode}`,{method:'POST',body:JSON.stringify({name:$('name').value.trim(),email:$('email').value.trim(),password:$('password').value})});setIdentity({...data.user,token:data.token});localStorage.setItem(SESSION,JSON.stringify(state.identity));auth(false);await openPicker()}catch(e){$('auth-error').textContent=e.message}}
function setup(){const room=$('room');room.required=false;room.hidden=true;document.querySelector('label[for="room"]').hidden=true;$('join-form').onsubmit=submitAuth;$('auth-toggle').dataset.mode='register';$('auth-toggle').onclick=toggleAuth;$('compose').onsubmit=sendMessage;$('add-channel').onclick=addChannel;$('leave').onclick=openPicker;document.querySelector('.server.home').onclick=openPicker;document.querySelector('.server.add').onclick=openPicker;$('voice-channel').onclick=()=>{$('voice-state').innerHTML='<strong>Voz em breve</strong>Estamos preparando a conexão de voz estável para o aplicativo.'}}
async function boot(){setup();const saved=JSON.parse(localStorage.getItem(SESSION)||'null');if(!saved?.token)return auth(true);setIdentity(saved);auth(false);await openPicker()}boot();

// Controle local de microfone, preservado no cliente desktop enquanto a voz em grupo é evoluída.
let microphoneStream=null;
async function startVoice(){if(microphoneStream)return;try{microphoneStream=await navigator.mediaDevices.getUserMedia({audio:{deviceId:readSettings().input?{exact:readSettings().input}:undefined,echoCancellation:true,noiseSuppression:true,autoGainControl:readSettings().autoGain!==false}});$('voice-channel').classList.add('active');$('voice-state').innerHTML='<strong>Microfone conectado</strong>Pronto para entrar em uma conversa de voz.';$('mute').disabled=false}catch(error){$('voice-state').innerHTML=`<strong>Microfone indisponível</strong>${error.message}`}}
function stopVoice(){microphoneStream?.getTracks().forEach(track=>track.stop());microphoneStream=null;$('voice-channel').classList.remove('active');$('mute').disabled=true;$('voice-state').innerHTML='<strong>Não conectado</strong>Escolha um canal de voz para falar.'}
$('voice-channel').onclick=startVoice;$('mute').onclick=()=>{const track=microphoneStream?.getAudioTracks()[0];if(!track)return;track.enabled=!track.enabled;$('mute').textContent=track.enabled?'🎙':'🔇'};$('leave').onclick=()=>{stopVoice();openPicker()};

// Criação de comunidade: cada servidor possui convite, canais e mensagens isolados.
const creator=document.createElement('section');creator.className='join-modal';creator.id='server-creator';creator.hidden=true;creator.innerHTML='<form class="join-card" id="server-creator-form"><h1>Crie seu servidor</h1><p>Seu espaço começa com os canais #geral e #boas-vindas.</p><label for="new-server-name">NOME DO SERVIDOR</label><input id="new-server-name" maxlength="32" placeholder="Ex.: Comunidade Vix" required autofocus><p id="server-creator-error" role="alert"></p><button>Criar meu servidor</button><button id="server-creator-cancel" type="button" style="margin-top:10px;background:transparent;color:#b5bac1">Cancelar</button></form>';document.body.append(creator);
const showCreator=()=>{creator.hidden=false;$('new-server-name').value='';$('server-creator-error').textContent='';setTimeout(()=>$('new-server-name').focus(),0)};
$('picker-create').onclick=showCreator;document.querySelector('.server.add').onclick=showCreator;$('server-creator-cancel').onclick=()=>creator.hidden=true;creator.onclick=event=>{if(event.target===creator)creator.hidden=true};$('server-creator-form').onsubmit=async event=>{event.preventDefault();const name=$('new-server-name').value.trim();try{const server=await api('/api/servers',{method:'POST',body:JSON.stringify({name})});creator.hidden=true;await loadServer(server)}catch(error){$('server-creator-error').textContent=error.message}};
const inviteButton=document.createElement('button');inviteButton.type='button';inviteButton.textContent='Convidar';inviteButton.hidden=true;inviteButton.style.cssText='margin-left:auto;border:0;border-radius:4px;background:#5865f2;color:#fff;padding:6px 10px;font-size:12px;font-weight:700;cursor:pointer';inviteButton.onclick=async()=>{if(!state.server)return;try{await navigator.clipboard.writeText(state.server.invite);inviteButton.textContent='Convite copiado!';setTimeout(()=>inviteButton.textContent='Convidar',1600)}catch{prompt('Compartilhe este código de convite:',state.server.invite)}};document.querySelector('.header').append(inviteButton);
const loadIndividualServer=loadServer;loadServer=async server=>{await loadIndividualServer(server);if(state.server?.id===server.id)inviteButton.hidden=false};

// Criação de sala/canal sem usar prompts do navegador, que podem ser bloqueados no aplicativo.
const channelCreator=document.createElement('section');channelCreator.className='join-modal';channelCreator.id='channel-creator';channelCreator.hidden=true;channelCreator.innerHTML='<form class="join-card" id="channel-creator-form"><h1>Criar canal</h1><p>Crie uma sala de texto exclusiva neste servidor.</p><label for="new-channel-name">NOME DO CANAL</label><input id="new-channel-name" maxlength="32" placeholder="Ex.: avisos" required autofocus><p id="channel-creator-error" role="alert"></p><button>Criar canal</button><button id="channel-creator-cancel" type="button" style="margin-top:10px;background:transparent;color:#b5bac1">Cancelar</button></form>';document.body.append(channelCreator);
function showChannelCreator(){if(!state.server)return openPicker();channelCreator.hidden=false;$('new-channel-name').value='';$('channel-creator-error').textContent='';setTimeout(()=>$('new-channel-name').focus(),0)}
$('add-channel').onclick=showChannelCreator;$('channel-creator-cancel').onclick=()=>channelCreator.hidden=true;channelCreator.onclick=event=>{if(event.target===channelCreator)channelCreator.hidden=true};$('channel-creator-form').onsubmit=async event=>{event.preventDefault();const name=$('new-channel-name').value.trim();try{await api(`/api/servers/${state.server.id}/channels`,{method:'POST',body:JSON.stringify({name})});channelCreator.hidden=true;await loadServer(state.server)}catch(error){$('channel-creator-error').textContent=error.message}};

// Painel de voz do desktop: controles reais de mídia e estado claro de conexão.
let cameraStream=null,screenStream=null,deafened=false;
function mediaButton(icon,label,handler){const button=document.createElement('button');button.type='button';button.textContent=icon;button.title=label;button.setAttribute('aria-label',label);button.style.cssText='border:0;border-radius:7px;background:#41434a;color:#f2f3f5;min-width:42px;height:34px;font-size:17px;cursor:pointer';button.onclick=handler;return button}
function renderVoicePanel(){const panel=$('voice-state');if(!microphoneStream){panel.innerHTML='<strong>Não conectado</strong>Escolha um canal de voz para falar.';return}panel.replaceChildren();const title=document.createElement('strong'),copy=document.createElement('span'),controls=document.createElement('div');title.textContent=screenStream?'Compartilhando tela':'Voz conectada';copy.textContent=`${selectedVoiceChannel.name}${cameraStream?' · câmera ligada':''}${deafened?' · fone silenciado':''}`;copy.style.cssText='display:block;margin-bottom:9px';controls.style.cssText='display:flex;gap:6px;flex-wrap:wrap';const mic=mediaButton(microphoneStream.getAudioTracks()[0]?.enabled?'🎙':'🔇','Ativar ou silenciar microfone',()=>{const track=microphoneStream?.getAudioTracks()[0];if(track)track.enabled=!track.enabled;renderVoicePanel()});const headphones=mediaButton(deafened?'🔇':'🎧','Silenciar áudio recebido',()=>{deafened=!deafened;renderVoicePanel()});const camera=mediaButton(cameraStream?'📹':'📷','Ligar ou desligar câmera',async()=>{if(cameraStream){cameraStream.getTracks().forEach(track=>track.stop());cameraStream=null;return renderVoicePanel()}try{cameraStream=await navigator.mediaDevices.getUserMedia({video:true});renderVoicePanel()}catch(error){alert(`Câmera indisponível: ${error.message}`)}});const share=mediaButton(screenStream?'🖥':'↗','Compartilhar tela',async()=>{if(screenStream){screenStream.getTracks().forEach(track=>track.stop());screenStream=null;return renderVoicePanel()}try{screenStream=await navigator.mediaDevices.getDisplayMedia(screenCaptureOptions());screenStream.getVideoTracks()[0]?.addEventListener('ended',()=>{screenStream=null;renderVoicePanel()});renderVoicePanel()}catch(error){if(error.name!=='AbortError')alert(`Não foi possível compartilhar a tela: ${error.message}`)}});const activity=mediaButton('✦','Iniciar atividade',()=>alert('Atividades compartilhadas serão a próxima evolução do Vix Voice.'));const leave=mediaButton('☎','Desconectar da voz',()=>stopVoice());leave.style.background='#da373c';controls.append(mic,headphones,camera,share,activity,leave);panel.append(title,copy,controls)}
const baseStartVoice=startVoice,baseStopVoice=stopVoice;startVoice=async()=>{await baseStartVoice();if(microphoneStream)renderVoicePanel()};stopVoice=()=>{cameraStream?.getTracks().forEach(track=>track.stop());screenStream?.getTracks().forEach(track=>track.stop());cameraStream=null;screenStream=null;deafened=false;baseStopVoice();renderVoicePanel()};$('voice-channel').onclick=startVoice;$('leave').onclick=()=>{stopVoice();openPicker()};

// Central da comunidade: atalhos e categorias inspirados na navegação de servidores.
const community=document.createElement('div');community.id='community-tools';community.style.cssText='padding:10px 12px 8px;border-bottom:1px solid #3f4147;display:grid;gap:4px';community.innerHTML='<button data-community="events">▣&nbsp; Eventos</button><button data-community="browse">☷&nbsp; Conferir canais</button><button data-community="members">♟&nbsp; Membros</button><button data-community="boost">♢&nbsp; Impulsos de servidor</button>';document.querySelector('.channel-scroll').before(community);for(const button of community.querySelectorAll('button'))button.style.cssText='border:0;background:transparent;color:#b5bac1;text-align:left;padding:6px 2px;font-size:14px;cursor:pointer';
const communityModal=document.createElement('section');communityModal.className='join-modal';communityModal.hidden=true;communityModal.innerHTML='<div class="join-card"><h1 id="community-title"></h1><div id="community-content"></div><button id="community-close" type="button" style="margin-top:14px;background:#41434a">Fechar</button></div>';document.body.append(communityModal);$('community-close').onclick=()=>communityModal.hidden=true;communityModal.onclick=event=>{if(event.target===communityModal)communityModal.hidden=true};
function openCommunity(title,content){$('community-title').textContent=title;const box=$('community-content');box.replaceChildren();content(box);communityModal.hidden=false}
function eventKey(){return `vix-events-${state.server?.id||'none'}`}
function eventsView(){openCommunity('Eventos',box=>{const events=JSON.parse(localStorage.getItem(eventKey())||'[]');const copy=document.createElement('p');copy.textContent=events.length?'Próximos eventos desta comunidade:':'Nenhum evento agendado neste servidor.';box.append(copy);for(const item of events){const row=document.createElement('div');row.style.cssText='padding:9px;margin:7px 0;border-radius:6px;background:#41434a';row.textContent=`▣ ${item.name} · ${item.when}`;box.append(row)}const create=document.createElement('button');create.textContent='Criar evento';create.style.marginTop='8px';create.onclick=()=>{const name=prompt('Nome do evento:')?.trim(),when=prompt('Data e horário:')?.trim();if(!name||!when)return;events.push({name,when});localStorage.setItem(eventKey(),JSON.stringify(events));eventsView()};box.append(create)})}
function browseView(){openCommunity('Conferir canais',box=>{const copy=document.createElement('p');copy.textContent='Escolha um canal para abrir.';box.append(copy);for(const channel of document.querySelectorAll('#text-channels .channel')){const button=document.createElement('button');button.textContent=channel.textContent.trim();button.style.cssText='margin:4px 0;background:#41434a;text-align:left';button.onclick=()=>{channel.click();communityModal.hidden=true};box.append(button)}})}
function membersView(){openCommunity('Membros',box=>{const copy=document.createElement('p');copy.textContent=state.server?'Os membros online aparecem à direita.':'Abra um servidor para ver seus membros.';box.append(copy);const me=document.createElement('div');me.style.cssText='padding:9px;border-radius:6px;background:#41434a';me.textContent=state.identity?`● ${state.identity.name} (você)`:'';box.append(me)})}
function boostView(){openCommunity('Impulsos de servidor',box=>{const copy=document.createElement('p');copy.textContent='Impulsos permitem personalizar a comunidade com recursos extras. Este servidor está no nível 0.';box.append(copy);const note=document.createElement('small');note.textContent='O sistema de níveis e benefícios será conectado à assinatura quando o Vix Voice estiver pronto para lançamento.';box.append(note)})}
community.querySelector('[data-community="events"]').onclick=eventsView;community.querySelector('[data-community="browse"]').onclick=browseView;community.querySelector('[data-community="members"]').onclick=membersView;community.querySelector('[data-community="boost"]').onclick=boostView;

// Participantes presentes no canal de voz.
let voiceRefreshSequence=0;
async function refreshVoiceUsers(){const serverId=state.server?.id;if(!serverId)return;const sequence=++voiceRefreshSequence;try{const {users}=await api(`/api/servers/${serverId}/voice`);if(state.server?.id!==serverId||sequence!==voiceRefreshSequence)return;if(window.renderVoiceChannelUsers){window.renderVoiceChannelUsers(users);return}const list=$('voice-users');const signature=JSON.stringify([serverId,users]);if(list.dataset.presence===signature)return;list.dataset.presence=signature;list.replaceChildren();for(const user of users){const row=document.createElement('div');row.className='voice-user';row.dataset.voiceUserId=user.user_id;row.style.cssText='display:flex;align-items:center;gap:6px;padding:4px 12px;color:#dbdee1;font-size:13px';const avatar=document.createElement('span');avatar.textContent=initials(user.name);avatar.style.cssText=`display:inline-grid;place-items:center;width:22px;height:22px;border-radius:50%;background:${user.color};font-size:9px;font-weight:800`;const name=document.createElement('span');name.textContent=user.user_id===state.identity?.id?'Você':user.name;row.append(avatar,name);list.append(row)}}catch(error){console.warn('Presença de voz indisponível',error)}}
const presenceStartVoice=startVoice,presenceStopVoice=stopVoice;startVoice=async()=>{await presenceStartVoice();if(microphoneStream&&state.server){try{await api(`/api/servers/${state.server.id}/voice`,{method:'POST',body:JSON.stringify({channel:selectedVoiceChannel.id})});await refreshVoiceUsers()}catch(error){console.warn('Presença de voz indisponível; continuando a conexão.',error)}}};stopVoice=()=>{if(state.server&&state.identity)api(`/api/servers/${state.server.id}/voice`,{method:'DELETE'}).catch(()=>{});presenceStopVoice();delete $('voice-users').dataset.presence;refreshVoiceUsers()};$('voice-channel').onclick=startVoice;$('leave').onclick=()=>{stopVoice();openPicker()};setInterval(refreshVoiceUsers,12000);

// Configurações de canal: disponíveis apenas para Dono/Admin.
const channelSettings=document.createElement('section');channelSettings.className='join-modal';channelSettings.hidden=true;channelSettings.innerHTML='<form class="join-card" id="channel-settings-form"><h1>Configurações do canal</h1><p id="channel-settings-copy"></p><label for="channel-settings-name">NOME DO CANAL</label><input id="channel-settings-name" maxlength="32" required><p id="channel-settings-error" role="alert"></p><button>Salvar alterações</button><button id="channel-delete" type="button" style="margin-top:10px;background:#da373c">Excluir canal</button><button id="channel-settings-close" type="button" style="margin-top:10px;background:transparent;color:#b5bac1">Cancelar</button></form>';document.body.append(channelSettings);let editingChannel=null;$('channel-settings-close').onclick=()=>channelSettings.hidden=true;channelSettings.onclick=event=>{if(event.target===channelSettings)channelSettings.hidden=true};
function openChannelSettings(channel){editingChannel=channel;$('channel-settings-name').value=channel;$('channel-settings-copy').textContent=`Você é ${state.server.role}. Pode editar este canal.`;$('channel-settings-error').textContent='';$('channel-delete').hidden=channel==='geral';channelSettings.hidden=false}
$('channel-settings-form').onsubmit=async event=>{event.preventDefault();try{const result=await api(`/api/servers/${state.server.id}/channels/${encodeURIComponent(editingChannel)}`,{method:'PATCH',body:JSON.stringify({name:$('channel-settings-name').value})});channelSettings.hidden=true;state.channel=result.name;await loadServer(state.server)}catch(error){$('channel-settings-error').textContent=error.message}};$('channel-delete').onclick=async()=>{if(!confirm(`Excluir #${editingChannel} e todas as mensagens dele?`))return;try{await api(`/api/servers/${state.server.id}/channels/${encodeURIComponent(editingChannel)}`,{method:'DELETE'});channelSettings.hidden=true;state.channel='geral';await loadServer(state.server)}catch(error){$('channel-settings-error').textContent=error.message}};
const normalRenderChannels=renderChannels;renderChannels=channels=>{normalRenderChannels(channels);const canManage=['Dono','Admin'].includes(state.server?.role);$('add-channel').hidden=!canManage;for(const [index,button] of [...$('text-channels').children].entries()){if(!canManage)continue;const gear=document.createElement('span');gear.textContent='⚙';gear.title='Configurações do canal';gear.style.cssText='margin-left:auto;padding:4px;color:#b5bac1;cursor:pointer';gear.onclick=event=>{event.stopPropagation();openChannelSettings(channels[index])};button.append(gear)}};
const roleAwareLoadServer=loadServer;loadServer=async server=>{await roleAwareLoadServer(server);const {servers}=await api('/api/servers');state.server=servers.find(item=>item.id===state.server?.id)||state.server;const channels=[...$('text-channels').children].map(button=>button.textContent.replace('⚙','').trim().replace(/^#/,'').trim());renderChannels(channels);await refreshVoiceUsers()};

// Evita conectar voz no servidor visual padrão; presença precisa de um servidor real.
