function deviceOptions(kind,selected){return navigator.mediaDevices?.enumerateDevices?.().then(items=>items.filter(item=>item.kind===kind).map(item=>`<option value="${item.deviceId}" ${item.deviceId===selected?'selected':''}>${item.label||`${kind==='audioinput'?'Microfone':'Alto-falante'} padrão`}</option>`).join('')).catch(()=>'<option>Dispositivo padrão</option>')}
async function renderSettingsVoice(){const data=readSettings(),content=$('settings-content'),inputs=await deviceOptions('audioinput',data.input),outputs=await deviceOptions('audiooutput',data.output);content.innerHTML=`<h1 style="margin:0 0 28px;font-size:25px">Voz</h1><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px"><label>Microfone<select id="settings-input">${inputs}</select></label><label>Alto-falante<select id="settings-output">${outputs}</select></label><label>Volume do microfone<input id="settings-input-volume" type="range" min="0" max="100" value="${data.inputVolume??100}"></label><label>Volume do alto-falante<input id="settings-output-volume" type="range" min="0" max="100" value="${data.outputVolume??100}"></label></div><div style="display:flex;align-items:center;gap:16px;margin-top:25px"><button id="settings-test-mic" class="settings-primary">Testar microfone</button><div id="settings-meter" style="height:20px;flex:1;border-radius:5px;background:repeating-linear-gradient(90deg,#4e5058 0 4px,transparent 4px 8px)"></div></div><p style="color:#b5bac1">Escolha seus dispositivos e teste o nível do microfone antes de entrar na sala.</p><hr><h2 style="font-size:17px">Perfil de entrada</h2><label class="settings-switch">Ajustar automaticamente a sensibilidade de entrada <input id="settings-auto-gain" type="checkbox" ${data.autoGain!==false?'checked':''}></label><p style="color:#b5bac1">Reduz ruído e ajusta o ganho do microfone automaticamente.</p>`;bindVoiceSettings()}
function renderSettingsSimple(view){const content=$('settings-content'),config={account:['Minha conta','Gerencie as informações usadas no Vix Voice.','Abrir edição de perfil'],profile:['Perfil','Altere sua foto, nome e aparência do perfil.','Editar perfil'],privacy:['Dados e privacidade','Os dados de sua conta e servidores ficam protegidos pela sua sessão.','Limpar preferências locais'],notifications:['Notificações','Controle os alertas deste navegador.','Ativar notificações'],appearance:['Aparência','Escolha como o Vix Voice deve aparecer neste dispositivo.','Alternar contraste']},item=config[view];content.innerHTML=`<h1 style="margin:0 0 10px">${item[0]}</h1><p style="color:#b5bac1">${item[1]}</p><button id="settings-action" class="settings-primary" style="margin-top:20px">${item[2]}</button>`;$('settings-action').onclick=()=>{if(view==='profile'||view==='account'){userSettings.hidden=true;showProfile()}else if(view==='privacy'){localStorage.removeItem(settingsKey());alert('Preferências locais removidas.')}else if(view==='notifications'&&Notification?.requestPermission)Notification.requestPermission();else document.body.classList.toggle('vix-contrast')}}
function bindVoiceSettings(){const data=readSettings();for(const id of ['settings-input','settings-output','settings-input-volume','settings-output-volume','settings-auto-gain'])$(id).onchange=event=>{const key=id.replace('settings-','').replace(/-([a-z])/g,(_,letter)=>letter.toUpperCase()),value=event.target.type==='checkbox'?event.target.checked:event.target.value;saveSettings({[key]:value});if(id==='settings-output-volume')for(const peer of voicePeers.values())peer.audio.volume=Number(value)/100};$('settings-test-mic').onclick=async()=>{let stream;try{stream=microphoneStream||await navigator.mediaDevices.getUserMedia({audio:true}),context=new AudioContext(),source=context.createMediaStreamSource(stream),analyser=context.createAnalyser(),values=new Uint8Array(128),until=Date.now()+5000;source.connect(analyser);const tick=()=>{analyser.getByteTimeDomainData(values);const level=Math.min(100,values.reduce((sum,value)=>sum+Math.abs(value-128),0)/values.length*5);$('settings-meter').style.background=`linear-gradient(90deg,#23a559 ${level}%,#3f4147 ${level}%)`;if(Date.now()<until)requestAnimationFrame(tick);else{source.disconnect();context.close();if(stream!==microphoneStream)stream.getTracks().forEach(track=>track.stop())}};tick()}catch(error){alert(`Não foi possível testar o microfone: ${error.message}`)}}}
async function openUserSettings(){if(!state.identity)return;userSettings.hidden=false;$('settings-name').textContent=state.identity.name;$('settings-avatar').textContent=initials(state.identity.name);$('settings-avatar').style.background=state.identity.color||'#5865f2';const photo=localStorage.getItem(avatarKey());if(photo){$('settings-avatar').textContent='';$('settings-avatar').style.backgroundImage=`url("${photo}")`;$('settings-avatar').style.backgroundSize='cover'}settingsButtonStyle();for(const button of userSettings.querySelectorAll('#settings-nav button'))button.onclick=async()=>{for(const item of userSettings.querySelectorAll('#settings-nav button'))item.classList.remove('selected');button.classList.add('selected');$('settings-title').textContent=button.dataset.view==='voice'?'Voz e vídeo':button.textContent.trim();if(button.dataset.view==='voice')await renderSettingsVoice();else renderSettingsSimple(button.dataset.view)};await renderSettingsVoice()}
const settingsCss=document.createElement('style');settingsCss.textContent='#settings-nav button.selected,#settings-nav button:hover{background:#35373c!important;color:#fff!important}.settings-primary{border:0;border-radius:6px;background:#5865f2;color:#fff;padding:11px 15px;font-weight:700;cursor:pointer}.settings-switch{display:flex;justify-content:space-between;align-items:center;padding:14px 0;font-weight:700}#settings-content select,#settings-content input[type=range]{display:block;width:100%;margin-top:8px}#settings-content select{padding:10px;border:1px solid #3f4147;border-radius:5px;background:#111214;color:#fff}@media(max-width:600px){#settings-content{margin:28px auto!important}#settings-content>div{grid-template-columns:1fr!important}#settings-nav small,#settings-search{display:none!important}#settings-nav button{font-size:0!important;padding:12px!important}#settings-nav button::first-letter{font-size:17px}#settings-nav{margin-top:0!important}#settings-nav hr{display:none}#settings-content{padding:0 2px} }';document.head.append(settingsCss);
$('settings-close').onclick=()=>userSettings.hidden=true;$('settings-search').oninput=event=>{const term=event.target.value.toLowerCase();for(const button of userSettings.querySelectorAll('#settings-nav button'))button.hidden=!button.textContent.toLowerCase().includes(term)};$('leave').onclick=openUserSettings;

// Correções finais do painel: somente a engrenagem abre configurações, nunca o seletor de servidores.
userSettings.style.display='none';
deviceOptions=(kind,selected)=>Promise.resolve(navigator.mediaDevices?.enumerateDevices?.()||[]).then(items=>{const options=items.filter(item=>item.kind===kind).map(item=>`<option value="${item.deviceId}" ${item.deviceId===selected?'selected':''}>${item.label||'Dispositivo padrão'}</option>`).join('');return options||'<option value="">Dispositivo padrão</option>'}).catch(()=>'<option value="">Dispositivo padrão</option>');
const settingsOpenBase=openUserSettings;openUserSettings=async()=>{userSettings.hidden=false;userSettings.style.display='grid';try{await settingsOpenBase()}catch(error){console.warn('Configurações de voz indisponíveis',error);$('settings-content').innerHTML='<h1>Voz e vídeo</h1><p style="color:#b5bac1">Os dispositivos não estão disponíveis neste navegador.</p>'}};$('leave').onclick=openUserSettings;$('settings-close').onclick=()=>{userSettings.hidden=true;userSettings.style.display='none'};
const settingsFixCss=document.createElement('style');settingsFixCss.textContent='#settings-nav button{background:transparent!important;color:#b5bac1!important;border:0!important}#settings-nav button.selected,#settings-nav button:hover{background:#35373c!important;color:#fff!important}';document.head.append(settingsFixCss);

// Ganho real do microfone: o controle de volume altera o áudio enviado pela chamada.
let micGainContext=null,micGainNode=null,micGainStream=null;
async function applyMicrophoneVolume(value){const amount=Math.max(0,Math.min(2,Number(value)/100));saveSettings({inputVolume:Math.round(amount*100)});if(!microphoneStream)return;try{if(!micGainNode){micGainContext=new AudioContext();const source=micGainContext.createMediaStreamSource(microphoneStream),destination=micGainContext.createMediaStreamDestination();micGainNode=micGainContext.createGain();source.connect(micGainNode);micGainNode.connect(destination);micGainStream=destination.stream}micGainNode.gain.value=amount;if(micGainContext.state!=='running')await micGainContext.resume();const processed=micGainStream.getAudioTracks()[0];for(const peer of voicePeers.values()){const sender=peer.connection.getSenders().find(item=>item.track?.kind==='audio');if(sender)await sender.replaceTrack(processed)}}catch(error){console.warn('Não foi possível ajustar o ganho do microfone',error)}}
const volumePeer=ensureVoicePeer;ensureVoicePeer=person=>{const peer=volumePeer(person);const processed=micGainStream?.getAudioTracks()[0];if(processed){const sender=peer.connection.getSenders().find(item=>item.track?.kind==='audio');sender?.replaceTrack(processed).catch(()=>{})}return peer};
const volumeSettingsOpen=openUserSettings;openUserSettings=async()=>{await volumeSettingsOpen();const slider=$('settings-input-volume');if(slider){slider.oninput=event=>applyMicrophoneVolume(event.target.value);slider.onchange=event=>applyMicrophoneVolume(event.target.value)}};$('leave').onclick=openUserSettings;
const volumeStopVoice=stopVoice;stopVoice=()=>{micGainNode?.disconnect();micGainContext?.close().catch(()=>{});micGainContext=null;micGainNode=null;micGainStream=null;volumeStopVoice()};
const volumeStartVoice=startVoice;startVoice=async()=>{await volumeStartVoice();if(microphoneStream)await applyMicrophoneVolume(readSettings().inputVolume??100)};$('voice-channel').onclick=startVoice;
